(7686939, 1258841, 50641, '<td valign="top">ha!</td>', 'ha!', '2021-02-15 00:03:31.000000', NULL, 1),
(7686989, 1259053, 4008, '<td valign="top">I am trying to figure out what the anagram is (also looking at your image in the free study challenge).. never mind... it does not influence the score.</td>', 'I am trying to figure out what the anagram is (also looking at your image in the free study challenge).. never mind... it does not influence the score.', '2021-02-15 08:39:56.000000', NULL, 1),
(7686990, 1258885, 4008, '<td valign="top">I recognise the birdbath. What a beautiful birds you have in your garden. The softness of the feathers comes out great in this image. (an advanced editing I would throw a just a little bit more light on the head, just a bit)</td>', 'I recognise the birdbath. What a beautiful birds you have in your garden. The softness of the feathers comes out great in this image. (an advanced editing I would throw a just a little bit more light on the head, just a bit)', '2021-02-15 08:45:48.000000', NULL, 1),
(7686993, 1258960, 4008, '<td valign="top">Technically great, but I suggest to rotate the image approx. 70 degrees clockwise.</td>', 'Technically great, but I suggest to rotate the image approx. 70 degrees clockwise.', '2021-02-15 08:50:25.000000', NULL, 1),
(7686995, 1259023, 4008, '<td valign="top">Beautiful bird and image.</td>', 'Beautiful bird and image.', '2021-02-15 08:58:01.000000', NULL, 1),
(7686998, 1259080, 4008, '<td valign="top">Nice scene. It could do with a little bit of white balance correction.</td>', 'Nice scene. It could do with a little bit of white balance correction.', '2021-02-15 09:04:16.000000', NULL, 1),
(7687003, 1259040, 4008, '<td valign="top">Nice sharp dog portrait. The colours are great as well.</td>', 'Nice sharp dog portrait. The colours are great as well.', '2021-02-15 09:18:23.000000', NULL, 1),
(7687005, 1258709, 4008, '<td valign="top">I would apply a levels correction to it to get a bit more contrast, not too much, otherwise you loose the atmosphere, but enough to enhance colours and depth.</td>', 'I would apply a levels correction to it to get a bit more contrast, not too much, otherwise you loose the atmosphere, but enough to enhance colours and depth.', '2021-02-15 09:22:12.000000', NULL, 1),
(7687006, 1259044, 4008, '<td valign="top">If you apply "levels" to increase exposure, it brings out so much more warmth in the image.</td>', 'If you apply "levels" to increase exposure, it brings out so much more warmth in the image.', '2021-02-15 09:22:55.000000', NULL, 1),
(7687007, 1258743, 4008, '<td valign="top">Cleaver anagram, but I don''t like the picture that much.</td>', 'Cleaver anagram, but I don''t like the picture that much.', '2021-02-15 09:23:04.000000', NULL, 1),
